import { readdirSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

/**
 * The stylesheet's craft-floor rules (Task 13 audit), checked as text: jsdom cannot compute the cascade.
 * styles.css starts with the EXACT block (the approved demo's CSS, generated by scripts/port-demo-css.py): its literal
 * hex tokens, 999px pills etc. ARE the design, so the craft-floor rules below apply only to the rest of the file.
 */
// Normalised to LF: with core.autocrlf the working copy may be CRLF.
const full = readFileSync(join(process.cwd(), "styles.css"), "utf8").replace(/\r\n/g, "\n");
const EXACT_START = "/* ===== EXACT";
const EXACT_END = "/* ===== /EXACT ===== */\n";
const exactEnd = full.indexOf(EXACT_END) + EXACT_END.length;
const exact = full.slice(0, exactEnd);
// The T11 block is big-goal-demo.html's CSS ported value for value (its 999px chip is the design): like the EXACT
// block, it is left out of the craft floor.
const T11_START = "/* ===== T11 learn";
const T11_END = "/* ===== /T11 ===== */";
const rest = full.slice(exactEnd);
const css = rest.includes(T11_START) ? rest.slice(0, rest.indexOf(T11_START)) + rest.slice(rest.indexOf(T11_END) + T11_END.length) : rest;
const rules = [...css.matchAll(/([^{}]+)\{([^{}]*)\}/g)].map((m) => ({ sel: m[1]!.trim(), body: m[2]! }));
const declared = (re: RegExp): string[] => rules.filter((r) => re.test(r.body)).map((r) => r.sel);

const walk = (dir: string, keep: (name: string) => boolean): string[] => readdirSync(dir).flatMap((n) => {
  const p = join(dir, n);
  return statSync(p).isDirectory() ? walk(p, keep) : keep(n) ? [p] : [];
});

describe("styles.css base block (demo styling with native form fields)", () => {
  it("is the very top of styles.css and closed once", () => {
    expect(full.startsWith(EXACT_START)).toBe(true);
    expect(full.split(EXACT_END).length).toBe(2);
    expect(exact).toContain("body .ew .ew-modal{width:min(520px,calc(100vw - 32px))");
  });
  it("password fields share the text fields' full-width form styling", () => {
    const field = [...exact.matchAll(/([^{}]+)\{([^{}]*)\}/g)].find((rule) => rule[1]!.split(",").map((selector) => selector.trim()).includes("body .ew input[type=password]"));
    expect(field).toBeDefined();
    expect(field![1]).toContain("body .ew input[type=text]");
    for (const declaration of ["font:inherit", "color:var(--tx-1)", "background:var(--bg-1)", "border:1px solid var(--border)", "box-sizing:border-box", "width:100%"])
      expect(field![2]).toContain(declaration);
  });
  it("monochrome only: none of the banned accent tokens (plan global rule 3) in styles.css or any file under src", () => {
    const bad = new RegExp(["7c5" + "ce0", "9b8" + "3f0", "pur" + "ple", "vio" + "let"].join("|"), "i");
    expect(full).not.toMatch(bad);
    const hits = walk(join(process.cwd(), "src"), () => true).filter((f) => bad.test(readFileSync(f, "utf8")));
    expect(hits).toEqual([]);
  });
});

describe("styles.css evoui blocks: the demo's data palette (tone → token)", () => {
  // A rule right after a comment carries the comment in its selector text: matched by its last line.
  const body = (sel: string): string => rules.find((r) => r.sel.split("\n").pop()!.trim() === sel)?.body ?? "";
  it("tokens fall back to Obsidian's variables outside a wiki note", () => {
    const root = body(".evowiki-evoui");
    for (const t of ["--evoui-viz-1: var(--viz-1,", "--evoui-viz-2: var(--viz-2,", "--evoui-known: var(--known,",
      "--evoui-gap: var(--gap,", "--evoui-shaky: var(--shaky,"]) expect(root).toContain(t);
  });
  it("accent → --viz-1, warning → --viz-2 in data marks and --shaky as a state, success → --known, danger → --gap", () => {
    expect(body(".evowiki-evoui .t-accent")).toContain("var(--evoui-viz-1)");
    expect(body(".evowiki-evoui .t-warning")).toContain("var(--evoui-shaky)");
    expect(body(".evowiki-evoui .t-success")).toContain("var(--evoui-known)");
    expect(body(".evowiki-evoui .t-danger")).toContain("var(--evoui-gap)");
    for (const k of ["stroke", "fill", "lbl", "shape"]) {
      expect(body(`.evowiki-evoui .evoui-plot .${k}.t-accent`), k).toContain("var(--evoui-viz-1)");
      expect(body(`.evowiki-evoui .evoui-plot .${k}.t-warning`), k).toContain("var(--evoui-viz-2)");
      expect(body(`.evowiki-evoui .evoui-plot .${k}.t-success`), k).toContain("var(--evoui-known)");
      expect(body(`.evowiki-evoui .evoui-plot .${k}.t-danger`), k).toContain("var(--evoui-gap)");
    }
    expect(body(".evowiki-evoui .evoui-legend .t-warning")).toContain("var(--evoui-viz-2)");
    expect(body(".evowiki-evoui .evoui-quiz .opt.right")).toContain("var(--evoui-known)");
    expect(body(".evowiki-evoui .evoui-quiz .opt.wrong")).toContain("var(--evoui-gap)");
    expect(body('.evowiki-evoui .evoui-slider input[type="range"]')).toContain("accent-color: var(--evoui-viz-1)");
  });
});

describe("styles.css craft floor", () => {
  it("no colored side stripes on cards, rows or alerts (a left / right border wider than 1px)", () => {
    expect(declared(/border-(left|right|inline-start|inline-end)\s*:\s*(?!1px|0|none)\d/)).toEqual([]);
    expect(declared(/box-shadow\s*:\s*inset\s+\d+px\s+0\s+0/)).toEqual([]);
  });
  it("no all-caps headings, no hex colors, no pill radius, no external fonts", () => {
    expect(declared(/text-transform\s*:\s*uppercase/)).toEqual([]);
    expect(css).not.toMatch(/#[0-9a-fA-F]{3,8}\b(?![^{]*\{)/);
    expect(declared(/#[0-9a-fA-F]{3,8}\b/)).toEqual([]);
    // The demo-mapping sections (/* ===== T<n> … /* ===== /T<n> ===== */) re-create the demo's pills on Obsidian's DOM.
    const own = css.replace(/\/\* ===== T\d+[\s\S]*?\/\* ===== \/T\d+ ===== \*\//g, "");
    const ownRules = [...own.matchAll(/([^{}]+)\{([^{}]*)\}/g)].map((m) => ({ sel: m[1]!.trim(), body: m[2]! }));
    expect(ownRules.filter((r) => /border-radius\s*:\s*999px/.test(r.body)).map((r) => r.sel)).toEqual([]);
    expect(css).not.toMatch(/@import|@font-face|fonts\.googleapis/);
  });
  it("the section ⋯ (T10) has no transition at all (the 最近改了 dialog is gone: T12, the 参数 tab lists the changes)", () => {
    expect(rules.filter((r) => r.sel.includes(".ew-more")).every((r) => !/transition/.test(r.body))).toBe(true);
  });
  it("the composer's hidden file input stays hidden (the EXACT reset `body .ew input{all:revert}` re-shows [hidden] in Obsidian)", () => {
    const hide = rules.filter((r) => /display\s*:\s*none/.test(r.body)).map((r) => r.sel).join(",");
    expect(hide).toContain('body .ew .ew-asst input[type="file"][hidden]');
  });
  it("every draggable row can start a mouse drag in real Obsidian (the EXACT reset drops -webkit-user-drag on li)", () => {
    expect(declared(/-webkit-user-drag\s*:\s*element/).join(",")).toContain('body .ew [draggable="true"]');
  });
  it("学点新的 and the 助手's draft lists show no Obsidian hover tooltip from their aria-labels (the demo shows none)", () => {
    const off = declared(/--no-tooltip\s*:\s*true/).join(",");
    expect(off).toContain("body .ew-learn [aria-label]");
    expect(off).toContain("body .ew .ew-alist [aria-label]");
  });
  it("counts use tabular figures; explanatory lines are capped at a readable measure", () => {
    expect(declared(/font-variant-numeric\s*:\s*tabular-nums/).join(" ")).toContain(".evowiki-evoui .evoui-plot .tick");
  });

  it("every class a renderer emits has a CSS rule, unless it is a known hook-only class", () => {
    const styled = new Set([...full.matchAll(/\.(evowiki-[a-z0-9-]+)/g)].map((m) => m[1]!));
    const emitted = new Set<string>();
    for (const f of walk(join(process.cwd(), "src"), (n) => /\.ts$/.test(n) && !/\.test\.ts$|test-kit/.test(n))) {
      for (const lit of readFileSync(f, "utf8").matchAll(/"([^"\n]*evowiki-[^"\n]*)"|`([^`\n]*evowiki-[^`\n]*)`/g)) {
        for (const c of (lit[1] ?? lit[2] ?? "").matchAll(/(?<![\w-])(evowiki-[a-z0-9-]+)(?![a-z0-9-])/g)) emitted.add(c[1]!);
      }
    }
    const unstyled = [...emitted].filter((c) => !styled.has(c) && !HOOK_ONLY.has(c)).sort();
    expect(unstyled).toEqual([]);
  });
});

